    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost = -1
    for i in range(n):
        a, b, g, k = carpets[i]
        # The carpet covers x in [a, a+g) and y in [b, b+k)
        if a <= x < a + g and b <= y < b + k:
            topmost = i + 1  # 1-indexed
    return topmost

