def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque

    # Convert the number to a string for easier manipulation
    s = str(n)
    visited = set()
    queue = deque()

    # Start with the original number
    visited.add(s)
    queue.append(s)

    # Build a mapping from digit to list of possible transformations
    rule_map = {}
    for x, y in rules:
        if x not in rule_map:
            rule_map[x] = []
        rule_map[x].append(y)

    while queue:
        current = queue.popleft()
        # Try all possible transformations on each digit
        for i in range(len(current)):
            digit = current[i]
            if digit in rule_map:
                for new_digit in rule_map[digit]:
                    # Create the new number by replacing the digit
                    new_num_str = current[:i] + new_digit + current[i+1:]
                    # Skip if leading zero (unless the number is just "0")
                    if len(new_num_str) > 1 and new_num_str[0] == '0':
                        continue
                    if new_num_str not in visited:
                        visited.add(new_num_str)
                        queue.append(new_num_str)

    return len(visited)

