def jinjin_savings_plan(budgets: List[int]) -> int:
    from typing import List
    saved = 0
    for month in range(12):
        budget = budgets[month]
        if budget > 300:
            return -(month + 1)
        remaining = 300 - budget
        if remaining >= 100:
            save_amount = (remaining // 100) * 100
            saved += save_amount
    total = saved * 1.2 + (300 * 12 - sum(budgets))
    return int(total)

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Calculate longest increasing subsequence ending at each position
    inc = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Calculate longest decreasing subsequence starting at each position
    dec = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum choir formation length
    max_choir = 0
    for i in range(n):
        max_choir = max(max_choir, inc[i] + dec[i] - 1)

    return n - max_choir

def min_groups(w, n, prices):
    prices.sort()
    left = 0
    right = n - 1
    groups = 0

    while left <= right:
        if left == right:
            groups += 1
            break
        if prices[left] + prices[right] <= w:
            left += 1
            right -= 1
        else:
            right -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
