        return 0
    moves = 2
    for i in range(2, n + 1):
        moves = 2 * moves + 2
    return moves

def total_smoked_cigarettes(n, k):
    if k <= 1:
        return n
    total = n
    butts = n
    while butts >= k:
        new_cigs = butts // k
        total += new_cigs
        butts = butts % k + new_cigs
    return total
